/**
 * P5 — Executable Simulation Demos Verification for Adapter /3 (`hybrid-simulation-adapter/3`)
 * and `TypedFactNext` (`typed-fact-next/1`).
 *
 * Verifies real Scene3D payloads generated by Adapter /3 across 4 executable simulation demos:
 *   1. Demo 1: Pyramid S.ABCD with automatically derived unnamed section and derived sub-solid.
 *   2. Demo 2: Multiple related solids (S.ABC and D.ABC) with solid-qualified vertex identity & shared geometry.
 *   3. Demo 3: Step-by-step construction and highlighting with cutting plane perpendicular to SA.
 *   4. Demo 4: Negative underdetermined case refused cleanly with `scene3d === null`.
 */
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import * as THREE from "three";
import { describe, expect, it } from "vitest";
import type { Scene3D } from "./scene3d-model";
import { objectsAt } from "./scene3d-model";
import * as VIEW from "./scene3d-view";
import {
  deriveSectionSubEntities,
  entitiesPresentAt,
  sectionCycleLabel,
  sectionDetails,
  sectionFaceId,
  sectionVertexId,
  withSubEntities,
} from "./scene3d-subentities";
import {
  explode,
  isVisible,
  isolate,
  select,
  semanticTree,
  selectableIds,
  taoTrangThai,
} from "./interaction-state";

const DEMOS_DIR = resolve(
  __dirname,
  "../../../../../docs/evaluation/geometry/runs/typedfact-next-adapter3-simulation/demos",
);

function loadDemo(filename: string): Record<string, any> {
  const raw = readFileSync(resolve(DEMOS_DIR, filename), "utf-8");
  return JSON.parse(raw);
}

describe("P5 — Adapter /3 Executable Scene3D Simulation Demos", () => {
  it("Demo 1: renders pyramid + auto-derived unnamed section + derived sub-solid in Three.js without leaking internal IDs", () => {
    const demo1 = loadDemo("demo1-unnamed-section-pyramid.json");
    expect(demo1.adapter_version).toBe("hybrid-simulation-adapter/3");
    expect(demo1.contract_version).toBe("typed-fact-next/1");
    expect(demo1.route_d.status).toBe("SERVED");

    const scene = demo1.route_d.scene3d as Scene3D;
    expect(scene).toBeTruthy();
    const enriched = withSubEntities(scene);

    // 1. Both root pyramid and derived top pyramid exist as 3D meshes
    const solids = enriched.objects.filter((o) => o.type === "solid");
    expect(solids.length).toBe(2);
    const rootPyramid = solids.find((s) => s.id === "khoi_S_ABCD")!;
    const derivedPyramid = solids.find((s) => s.id !== "khoi_S_ABCD")!;
    expect(rootPyramid).toBeTruthy();
    expect(derivedPyramid).toBeTruthy();
    expect(derivedPyramid.notation).toBeNull();
    expect(derivedPyramid.label).toContain("Hình chóp cắt bởi (α) chứa đỉnh S");

    // 2. Unnamed derived section vertices have notation === null and descriptive Vietnamese labels
    const derivedVertices = demo1.route_d.derived_identities.filter(
      (d: any) => d.kind === "section_vertex",
    );
    expect(derivedVertices.length).toBe(3);
    for (const dv of derivedVertices) {
      const ptObj = enriched.objects.find((o) => o.id === dv.internal_symbol)!;
      expect(ptObj).toBeTruthy();
      expect(ptObj.notation).toBeNull();
      expect(ptObj.label).toContain("Giao điểm của");
    }

    // 3. Section sub-entities are derived and sectionCycleLabel returns null (does not invent "MI1I2I3")
    const secObj = enriched.objects.find((o) => o.type === "section")!;
    expect(secObj).toBeTruthy();
    expect(secObj.closed).toBe(true);
    expect(sectionCycleLabel(scene, secObj.id)).toBeNull();
    const subEntities = deriveSectionSubEntities(scene);
    expect(subEntities.map((e) => e.id)).toContain(sectionFaceId(secObj.id));
    expect(subEntities.map((e) => e.id)).toContain(sectionVertexId(secObj.id, 0));
    expect(subEntities.filter((e) => e.type === "edge")).toHaveLength(4);
    expect(subEntities.filter((e) => e.type === "point3")).toHaveLength(4);
    const details = sectionDetails(enriched, secObj.id)!;
    expect(details).toBeTruthy();

    // 4. Real Three.js Object3D construction succeeds for all visual objects
    for (const obj of enriched.objects) {
      if (obj.render === "non_visual" || obj.render === "readout") continue;
      const threeNode = VIEW.buildObject3D(obj, false);
      expect(threeNode).toBeInstanceOf(THREE.Object3D);
    }

    // 5. Certified math goals (volume_ratio = 1/8, residual_volume = 7a³/12)
    expect(demo1.route_d.answers.math_vol_ratio).toBe("1/8");
    expect(demo1.route_d.answers.math_res_vol).toBe("7a³/12");
  });

  it("Demo 2: renders multiple related solids with solid-qualified vertex identity and shared geometry", () => {
    const demo2 = loadDemo("demo2-multi-solid-shared-geometry.json");
    expect(demo2.route_d.status).toBe("SERVED");

    const scene = demo2.route_d.scene3d as Scene3D;
    const enriched = withSubEntities(scene);

    // Both pyramids S.ABC and D1.ABC are present in the same root coordinate frame
    const pyr1 = enriched.objects.find((o) => o.id === "khoi_S_ABC")!;
    const pyr2 = enriched.objects.find((o) => o.id === "khoi_D1_ABC")!;
    expect(pyr1).toBeTruthy();
    expect(pyr2).toBeTruthy();

    // Shared base vertices A, B, C have a single canonical object ID shared by both solids
    for (const v of ["A", "B", "C"]) {
      expect(pyr1.vertex_ids).toContain(v);
      expect(pyr2.vertex_ids).toContain(v);
      expect(enriched.objects.filter((o) => o.id === v).length).toBe(1);
    }

    // Colliding vertex name D is disambiguated between pyr1::D ("D") and pyr2::D ("D1")
    const ptD1 = enriched.objects.find((o) => o.id === "D")!;
    const ptD2 = enriched.objects.find((o) => o.id === "D1")!;
    expect(ptD1).toBeTruthy();
    expect(ptD2).toBeTruthy();
    expect(ptD2.notation).toBe("D(pyr2)");
    expect((ptD2.source as any).qualified_ref).toBe("pyr2::D");

    // Interactive state (selection, isolation, explosion) works across multiple solids
    const tree = semanticTree(enriched);
    expect(selectableIds(tree)).toContain("khoi_S_ABC");
    expect(selectableIds(tree)).toContain("khoi_D1_ABC");
    let st = select(taoTrangThai(), "khoi_D1_ABC");
    expect(st.selected_id).toBe("khoi_D1_ABC");
    st = isolate(st, ["khoi_D1_ABC"]);
    const present = entitiesPresentAt(enriched, 99, objectsAt);
    expect(isVisible(st, "khoi_D1_ABC", present)).toBe(true);
    expect(isVisible(st, "khoi_S_ABC", present)).toBe(false);
    st = explode(st, "solid");
    expect(st.exploded_groups).toContain("solid");
  });

  it("Demo 3: supports step-by-step construction playback and target highlighting", () => {
    const demo3 = loadDemo("demo3-step-by-step-construction-highlight.json");
    expect(demo3.route_d.status).toBe("SERVED");

    const scene = demo3.route_d.scene3d as Scene3D;
    const enriched = withSubEntities(scene);

    // Step-by-step playback monotonically builds the scene from step 0 to final step
    const totalSteps = scene.events.length;
    expect(totalSteps).toBeGreaterThan(4);
    const step0Objects = objectsAt(enriched, 0);
    const finalObjects = objectsAt(enriched, totalSteps - 1);
    expect(finalObjects.length).toBeGreaterThan(step0Objects.length);

    // Highlighted geometry goals mark target objects in display_group
    const secObj = enriched.objects.find((o) => o.type === "section")!;
    const mObj = enriched.objects.find((o) => o.id === "M")!;
    expect(secObj.display_group).toContain("target");
    expect(mObj.display_group).toContain("target");

    // Semantic tree organizes solids, section, constructions, and measurements
    const tree = semanticTree(enriched);
    expect(tree.length).toBeGreaterThan(0);

    // Exact volume ratio = (1/3)^3 = 1/27
    expect(demo3.route_d.answers.m_ratio).toBe("1/27");
  });

  it("Demo 4: cleanly refuses underdetermined geometry without fabricating a 3D scene", () => {
    const demo4 = loadDemo("demo4-negative-underdetermined-refusal.json");
    expect(demo4.route_d.status).toBe("REFUSED");
    expect(demo4.route_d.refusal.code).toBe("UNDERDETERMINED_POINT");
    expect(demo4.route_d.scene3d).toBeNull();
    expect(demo4.route_b.status).toBe("REFUSED");
    expect(demo4.route_b.scene3d).toBeNull();
    expect(demo4.comparison.scene3d_bucket).toBe("NEITHER");
  });
});
